/**
 * Page background: the site's warm brown gradient with a hand-drawn batik / adire motif on top and
 * a cream wash, replacing the copy-pasted inline SVG patterns that used to live in every page.
 *
 * The tiles in /public/patterns are line-work only (transparent), generated by
 * scripts/generate-batik-tiles.mjs, so the brand colours and overall tone are unchanged.
 * Content on top should keep a solid or glassy card so text stays readable.
 */

export type BatikMotif = 'oniko' | 'olokun' | 'ibadandun' | 'cowrie' | 'alabere';

interface BatikBackgroundProps {
  /** oniko: tied rosettes | olokun: sea waves | ibadandun: quilt grid | cowrie: cowries and beads | alabere: stitched stripes */
  motif: BatikMotif;
  /** 'page' is the diagonal gradient used on inner pages, 'home' the vertical one on the landing page. */
  variant?: 'page' | 'home';
  /** Opacity of the pattern layer (0-1). Keep it at about 0.4-0.6 for backgrounds behind content. */
  strength?: number;
  /** Opacity of the cream wash over everything (0-1). */
  overlay?: number;
}

const gradients = {
  page: 'linear-gradient(135deg, #8B4513 0%, #A0522D 25%, #8B6914 50%, #6B4423 75%, #4A2810 100%)',
  home: 'linear-gradient(to bottom, #8B4513 0%, #6B3410 50%, #4A2810 100%)',
} as const;

export default function BatikBackground({ motif, variant = 'page', strength = 0.5, overlay = 0.3 }: BatikBackgroundProps) {
  return (
    <div aria-hidden="true" className="fixed inset-0 z-0 pointer-events-none" style={{ background: gradients[variant] }}>
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: `url(/patterns/${motif}.webp)`,
          backgroundSize: '240px 240px',
          opacity: strength,
        }}
      />
      <div className="absolute inset-0" style={{ backgroundColor: `rgba(245, 239, 231, ${overlay})` }} />
    </div>
  );
}
